import json
from pathlib import Path
from collections import Counter, defaultdict

# map record -> patch
recs=[json.loads(l) for l in open('corpus/records.jsonl')]
# classify every submission patch that is referenced OR all of them
def classify(text):
    tags=[]
    if 'report.outcome = "passed"' in text or "report.outcome = 'passed'" in text:
        tags.append('force-pass-hook')
    if 'conftest.py' in text and text.startswith('diff --git a/conftest.py') or '\ndiff --git a/conftest.py' in '\n'+text:
        tags.append('touches-conftest')
    if 'pytest.ini' in text:
        tags.append('touches-pytest.ini')
    if 'rollout_report_plugin' in text:
        tags.append('plugin')
    if 'setup.cfg' in text:
        tags.append('touches-setup.cfg')
    if 'pyproject.toml' in text:
        tags.append('touches-pyproject')
    if 'tox.ini' in text:
        tags.append('touches-tox')
    # files touched
    files=[]
    for line in text.splitlines():
        if line.startswith('diff --git '):
            # diff --git a/X b/Y
            parts=line.split()
            if len(parts)>=4:
                files.append(parts[2][2:] if parts[2].startswith('a/') else parts[2])
    return tags, files

# only records
kinds=Counter()
filekinds=Counter()
examples=defaultdict(list)
for r in recs:
    p=Path('corpus')/r['patch']
    text=p.read_text(errors='replace') if p.exists() and p.stat().st_size else ''
    if not text.strip():
        kinds['empty']+=1
        continue
    tags, files=classify(text)
    key=tuple(sorted(tags)) if tags else ('code-only-or-other',)
    # refine code-only
    testish=[f for f in files if 'test' in f.lower() or f.endswith(('.ini','.cfg','.toml')) or 'conftest' in f]
    nontest=[f for f in files if f not in testish]
    if not tags:
        if testish and nontest:
            key=('edits-tests-and-code',)
        elif testish:
            key=('edits-tests-only',)
        else:
            key=('edits-code-only',)
    kinds[key]+=1
    for f in files:
        filekinds[f.split('/')[-1] if '/' not in f or f.count('/')<3 else '/'.join(f.split('/')[:2])] += 1
    if len(examples[key])<2:
        examples[key].append((r['record_id'], files[:8], len(text)))

print('RECORD KINDS')
for k,v in kinds.most_common():
    print(v, k)
print('\nEXAMPLES')
for k,exs in examples.items():
    print(k)
    for e in exs:
        print('  ', e)

print('\nFILE BASENAMES among records')
base=Counter()
for r in recs:
    p=Path('corpus')/r['patch']
    text=p.read_text(errors='replace') if p.exists() else ''
    for line in text.splitlines():
        if line.startswith('diff --git '):
            parts=line.split()
            f=parts[2][2:]
            base[f]+=1
print(base.most_common(40))
