import json
from pathlib import Path
from collections import Counter, defaultdict

recs=[json.loads(l) for l in open('corpus/records.jsonl')]
print('sample patch field', recs[0]['patch'], 'cwd files', Path('corpus/submissions').exists())
p=Path('corpus')/recs[0]['patch']
print(p, p.exists(), p.is_file())

def files_of(text):
    files=[]
    for line in text.splitlines():
        if line.startswith('diff --git '):
            parts=line.split()
            files.append(parts[2][2:])
    return files

kinds=Counter()
examples=defaultdict(list)
base=Counter()
n_empty=0
for r in recs:
    p=Path('corpus')/r['patch']
    if not p.is_file():
        kinds[('missing-file',)]+=1
        continue
    text=p.read_text(errors='replace')
    if not text.strip():
        n_empty+=1
        kinds[('empty',)]+=1
        continue
    files=files_of(text)
    for f in files:
        base[f]+=1
    tags=[]
    if 'report.outcome' in text:
        tags.append('force-pass')
    if any(f=='conftest.py' or f.endswith('/conftest.py') for f in files):
        tags.append('conftest')
    if any(f=='pytest.ini' for f in files):
        tags.append('pytest.ini')
    if any('rollout_report_plugin' in f for f in files):
        tags.append('plugin')
    if any(f.endswith(('setup.cfg','pyproject.toml','tox.ini','setup.py')) for f in files):
        tags.append('packaging')
    testish=[f for f in files if '/tests/' in f or f.startswith('tests/') or f.startswith('test_') or 'test' in Path(f).name]
    code=[f for f in files if f not in testish and not f.endswith(('.ini','.cfg','.toml')) and 'conftest' not in f and 'plugin' not in f]
    if tags:
        key=tuple(tags)
    elif testish and code:
        key=('edits-tests-and-code',)
    elif testish:
        key=('edits-tests-only',)
    else:
        key=('edits-code-only',)
    kinds[key]+=1
    if len(examples[key])<3:
        examples[key].append((r['record_id'], files[:6]))

print('empty', n_empty)
print('KINDS')
for k,v in kinds.most_common():
    print(v, k)
print('\nEXAMPLES')
for k,exs in examples.items():
    print(k)
    for e in exs:
        print('   ', e)
print('\nTOP FILES')
for f,c in base.most_common(50):
    print(c, f)
