    """A tracked path whose contents decide which tests run or what they report."""
    name = rel.rsplit("/", 1)[-1]
    if name in _REPORTING_NAMES:
        return True
    if name.startswith("test_") or name.endswith("_test.py"):
        return True
    # The tests tree, but not a package that merely happens to contain one.
    if rel == "tests" or rel.startswith("tests/") or "/tests/" in f"/{rel}":
        return True
    return False


