def lookup(statuses: Mapping[str, str], node_id: str) -> tuple[str | None, str | None]:
    """Resolve one required node id against the parsed statuses.

    Returns (key, status). `key` is the entry the node id resolved to, or None when the run
    said nothing about it.

    Matching is exact on the full node id. The task bank also stores a few ids truncated
    mid-name (`test_colored` for `test_colored_formatter`, `::test` for every
    `::test_*` of that class). Such an id is the group of reported ids it prefixes:
    the group passes only when every member passed, and fails when any member did not.
    A prefix of nothing was never reported.
    """
    for name in _candidates(node_id):
        if name in statuses:
            return name, statuses[name]
    extensions = [key for key in statuses if key.startswith(node_id)]
    if not extensions:
        return None, None
    member_statuses = [statuses[key] for key in extensions]
    if all(status == "PASSED" or status == "XFAIL" for status in member_statuses):
        return extensions[0], "PASSED"
    for status in member_statuses:
        if status not in ("PASSED", "XFAIL"):
            return extensions[0], status
    return extensions[0], member_statuses[0]

