def test_an_ambiguous_prefix_is_not_matched():
    statuses = {
        "tests/test_core.py::test_in": "FAILED",
        "tests/test_core.py::test_in_unsortable_container": "PASSED",
    }
    # `test_in` names both a real test and the start of another one.
    _, status = lookup(statuses, "tests/test_core.py::test_i")
    assert status is None
    # The real test still resolves exactly.
    _, status = lookup(statuses, "tests/test_core.py::test_in")
    assert status == "FAILED"


