    statuses = {"colorlog/tests/test_colorlog.py::test_colored_formatter": "PASSED"}
    key, status = lookup(statuses, "colorlog/tests/test_colorlog.py::test_colored")
    assert key == "colorlog/tests/test_colorlog.py::test_colored_formatter"
    assert status == "PASSED"

