        bad.append(("resolved-has-fail", r["record_id"], len(failed), len(missing)))
    if lab == "unresolved" and missing:
        bad.append(("unresolved-has-missing", r["record_id"], len(missing), len(failed)))
    if lab == "unresolved" and not failed and not missing:
        bad.append(("unresolved-empty", r["record_id"]))
