for i, h in hm.items():
    n = nm[i]
    key = f"{h['label']}->{n['label']}"
    moves[key]+=1
    if n["label"]=="resolved":
        resolved.append(i)
    elif n["label"]=="unscorable":
        unscorable.append(i)
    else:
        stay.append(i)
print("moves", dict(moves))
