    print(i, "exitnote", [x for x in n.get("notes",[]) if x.startswith("exit") or x.startswith("seconds") or "patch" in x or "empty" in x], "miss", len(n.get("missing") or []), "fail", len(n.get("failed") or []))
print("--- resolved count", len(resolved))
# notes distribution
notes_c = Counter()
for r in new:
    for n in r.get("notes") or []:
        if n.startswith("exit=") or n.startswith("seconds"):
            if n.startswith("exit="):
                notes_c[n.split("=")[0]+"="+n.split("=")[1] if False else n[:n.find("=")+1]+ (n.split("=",1)[1] if not n.startswith("seconds") else "")] 
        else:
            notes_c[n]+=1
exits = Counter()
for r in new:
    for n in r.get("notes") or []:
        if n.startswith("exit="):
            exits[n]+=1
print("exits", exits)
print("other notes", notes_c)
# unresolved with missing
print("unresolved with missing", sum(1 for r in new if r["label"]=="unresolved" and r.get("missing")))
print("resolved with missing/failed", sum(1 for r in new if r["label"]=="resolved" and (r.get("missing") or r.get("failed"))))
